/** One map sprite of a building picture. */
struct ForkMapSpriteData {
	uint16_t width; ///< Width in pixels.
	uint16_t height; ///< Height in pixels.
	int16_t x_offs; ///< Offset of the left side from the middle of the tile.
	int16_t y_offs; ///< Offset of the top from the top corner of the tile.
	const uint8_t *palette; ///< Colours, three bytes each.
	uint16_t palette_size; ///< Number of colours.
	const uint8_t *rle; ///< Run lengths and colour indices.
	size_t rle_size; ///< Size of the run length data.
};

